// @ts-nocheck
// Generated by cinematiques/outils/exporter_jeu.py from the HyperFrames project of the Glucksmann episodes: do not edit
// by hand, change the project, then export again.

/** The career's own toolkit, built on the shared one (Anime). */
export function createCuisine(Anime) {
  const window = { Anime };
  /* The research kitchen of the Glucksmann episodes: the paper look, the laboratory, the flour sack with his head, the
   * carafe of still water, the hand in a lab coat. Pure functions of their arguments: renders are identical. The shared
   * toolkit (Anime) gives the clock, the seeded randomness and the jaw envelope; the head and its jaw are the game's. */
  (function () {
    const C = (window.Cuisine = {});
    C.INK = "#2A1B12";
    C.CREAM = "#F6E9C8";
    C.MUSTARD = "#E0A526";
    C.ORANGE = "#D2552A";
    C.BROWN = "#5A2E1A";
    C.GREEN = "#2F4A3C";
    C.SKIN = "#F2C29B";
    const W = `stroke="#FFFFFF" stroke-width="6" stroke-linejoin="round"`;

    /** The cut paper: a white edge on every piece, and this shadow under it. */
    C.paper = (id) => `<filter id="${id}" x="-10%" y="-10%" width="125%" height="130%"><feDropShadow dx="5" dy="8" stdDeviation="3" flood-color="#000" flood-opacity="0.32"/></filter>`;

    /** The game's head, chin at (x, y), with its jaw that talks. */
    C.head = function (id, { x, y, k = 1, faces = ["glucksmann"] }) {
      const art = window.Anime.art(faces[0]);
      const hs = 1.36 * k;
      const hx = x - art.chin[0] * hs, hy = y - art.chin[1] * hs;
      const jx = hx + art.pose[0] * hs, jy = hy + art.pose[1] * hs;
      const cut = (box, px, py) => `<svg x="${px.toFixed(1)}" y="${py.toFixed(1)}" width="${(box[2] * hs).toFixed(1)}" height="${(box[3] * hs).toFixed(1)}" viewBox="${box.join(" ")}"><image href="${art.atlas}" width="${art.w}" height="${art.h}"/></svg>`;
      return { id, k, pivot: [jx + art.pivot[0] * hs, jy + art.pivot[1] * hs], markup: `<g id="${id}">${cut(art.head, hx, hy)}<g id="${id}-jaw">${cut(art.jaw, jx, jy)}</g></g>` };
    };
    /** Open the jaw of a head built by C.head: 0 closed, 1 wide open. */
    C.jaw = function (head, open) {
      document.getElementById(`${head.id}-jaw`).setAttribute("transform", `translate(0 ${(open * 22 * head.k).toFixed(1)}) rotate(${(open * 3).toFixed(1)} ${head.pivot[0].toFixed(1)} ${head.pivot[1].toFixed(1)})`);
    };

    const sticker = (id, n, x, y, turn, body) => `<g transform="translate(${x} ${y}) rotate(${turn})"><g id="${id}-st-${n}" opacity="0" data-layout-ignore>${body}</g></g>`;
    const word = (text, size, fill, extra = "") => `<text x="0" y="${size * 0.36}" text-anchor="middle" font-family="Alegreya Sans" font-weight="700" font-size="${size}" fill="${fill}" ${extra}>${text}</text>`;

    /**
     * The specimen: a sack of wheat flour with his head sticking out. Base of the sack at (x, y); k = 1 stands about
     * 760 px tall, head included. `${id}-in` is the group to squash or sway (its origin is the base, at 0 0);
     * `${id}-st-0` to `-3` are the travel stickers, hidden until a scene shows them.
     */
    C.sack = function (id, { x, y, k = 1, faces = ["glucksmann"] }) {
      const head = C.head(`${id}-head`, { x: 0, y: -366, k: 0.8, faces });
      const stickers =
        sticker(id, 0, -100, -306, -11, `<rect x="-78" y="-28" width="156" height="56" rx="8" fill="#FFFDF4" stroke="#C0262D" stroke-width="6"/><path d="M-62 0h22M-51 -11v22" stroke="#C0262D" stroke-width="7"/><g transform="translate(14 0)">${word("TBILISSI", 28, "#C0262D")}</g>`) +
        sticker(id, 1, 104, -302, 9, `<rect x="-62" y="-28" width="124" height="28" fill="#2F6BD3"/><rect x="-62" y="0" width="124" height="28" fill="#F5C400"/><rect x="-62" y="-28" width="124" height="56" rx="4" fill="none" stroke="#FFFFFF" stroke-width="5"/>${word("KIEV", 34, "#FFFFFF", `stroke="${C.INK}" stroke-width="7" paint-order="stroke"`)}`) +
        sticker(id, 2, -96, -80, 7, `<rect x="-82" y="-27" width="164" height="54" rx="6" fill="#F5C400" stroke="${C.INK}" stroke-width="5"/><path d="M-82 -27h164" stroke="${C.INK}" stroke-width="12" stroke-dasharray="12 12"/>${word("NEW YORK", 29, C.INK)}`) +
        sticker(id, 3, 102, -74, -8, `<rect x="-70" y="-27" width="140" height="18" fill="#1B1B1B"/><rect x="-70" y="-9" width="140" height="18" fill="#D2232A"/><rect x="-70" y="9" width="140" height="18" fill="#F5C400"/><rect x="-70" y="-27" width="140" height="54" rx="4" fill="none" stroke="#FFFFFF" stroke-width="5"/>${word("BERLIN", 31, "#FFFFFF", `stroke="${C.INK}" stroke-width="7" paint-order="stroke"`)}`);
      const markup = `<g id="${id}" transform="translate(${x} ${y}) scale(${k})"><g id="${id}-in">
        <ellipse cx="0" cy="-386" rx="152" ry="30" fill="#9C8B68" ${W}/>
        ${head.markup}
        <path d="M-184 0 L-168 -370 Q-118 -348 -58 -360 Q0 -372 58 -358 Q118 -346 168 -370 L184 0 Q0 16 -184 0Z" fill="#F3E9D2" ${W}/>
        <path d="M-150 -338 L-164 -12 M150 -338 L164 -12" stroke="#DDD0AE" stroke-width="6" fill="none" stroke-linecap="round"/>
        <path d="M-168 -370 Q-118 -348 -58 -360 Q0 -372 58 -358 Q118 -346 168 -370" stroke="#DDD0AE" stroke-width="5" fill="none" transform="translate(0 16)"/>
        <ellipse cx="0" cy="-208" rx="120" ry="60" fill="#C0392B" stroke="#FFFFFF" stroke-width="5"/>
        <text x="0" y="-184" text-anchor="middle" font-family="Bangers" font-size="74" fill="${C.CREAM}" letter-spacing="3" data-layout-allow-overlap>FARINE</text>
        <text x="0" y="-110" text-anchor="middle" font-family="Alegreya Sans" font-weight="700" font-size="35" fill="${C.BROWN}" data-layout-allow-overlap>DE BLÉ · TYPE 55</text>
        <text x="0" y="-22" text-anchor="middle" font-family="Alegreya Sans" font-weight="700" font-size="28" fill="#7A6636" data-layout-ignore>1 kg</text>
        ${stickers}
      </g></g>`;
      return { markup, head, inner: `${id}-in` };
    };

    /** The carafe of still water, base at (x, y); `${id}-in` wobbles around its base. Not one bubble. */
    C.carafe = function (id, { x, y, k = 1 }) {
      return `<g id="${id}" transform="translate(${x} ${y}) scale(${k})"><g id="${id}-in">
        <path d="M-34 -300 L-34 -232 Q-34 -200 -62 -170 Q-80 -150 -80 -110 L-80 -18 Q-80 0 -60 0 L60 0 Q80 0 80 -18 L80 -110 Q80 -150 62 -170 Q34 -200 34 -232 L34 -300Z" fill="#E9F3F6" ${W}/>
        <path d="M-73 -132 L73 -132 L73 -20 Q73 -7 58 -7 L-58 -7 Q-73 -7 -73 -20Z" fill="#9CC9DD"/>
        <path d="M-73 -132 L73 -132" stroke="#6FA9C2" stroke-width="5"/>
        <rect x="-43" y="-312" width="86" height="18" rx="7" fill="#CFE2E8" stroke="#FFFFFF" stroke-width="5"/>
        <path d="M-54 -112 L-54 -44" stroke="#FFFFFF" stroke-width="9" stroke-linecap="round" opacity="0.85"/>
        <g transform="rotate(-4 0 -74)"><rect x="-66" y="-100" width="132" height="52" fill="#FFFDF4" stroke="${C.INK}" stroke-width="4"/>
        <text x="0" y="-63" text-anchor="middle" font-family="Alegreya Sans" font-weight="700" font-size="30" fill="${C.INK}">EAU PLATE</text></g>
      </g></g>`;
    };

    /** A hand in a lab coat, pointing left; the fingertip is at (x, y). Move `${id}-in`. */
    C.hand = function (id, { x, y }) {
      return `<g id="${id}" transform="translate(${x} ${y})"><g id="${id}-in">
        <path d="M150 -56 L760 -84 L760 84 L150 56Z" fill="#FBFBF8" ${W}/>
        <rect x="128" y="-62" width="38" height="124" rx="9" fill="#E3E8EA" ${W}/>
        <path d="M46 -46 Q36 -54 66 -54 L130 -52 L130 52 L72 52 Q38 50 42 22Z" fill="${C.SKIN}" ${W}/>
        <path d="M0 -10 Q-4 -24 12 -25 L70 -27 L70 5 L12 5 Q-2 3 0 -10Z" fill="${C.SKIN}" ${W}/>
      </g></g>`;
    };

    const jar = (x, lines, inside) => `<g transform="translate(${x} 330)">
        <rect x="-76" y="-200" width="152" height="200" rx="16" fill="#E9F3F6" ${W}/>${inside}
        <rect x="-66" y="-226" width="132" height="34" rx="9" fill="#B9884F" ${W}/>
        <rect x="-70" y="-150" width="140" height="${lines.length * 32 + 18}" fill="#FFFDF4" stroke="${C.INK}" stroke-width="3"/>
        ${lines.map((line, i) => `<text x="0" y="${-114 + i * 32}" text-anchor="middle" font-family="Alegreya Sans" font-weight="700" font-size="30" fill="${C.INK}">${line}</text>`).join("")}
      </g>`;

    /** The tiled wall of the laboratory, with the paper shadow `${p}-paper` every scene uses. */
    C.wall = function (p) {
      return `<defs>${C.paper(`${p}-paper`)}
        <pattern id="${p}-tiles" patternUnits="userSpaceOnUse" width="96" height="96"><rect width="96" height="96" fill="#D3E2D6"/><path d="M0 0H96M0 0V96" stroke="#F4F8F3" stroke-width="5"/></pattern></defs>
      <rect width="1920" height="1080" fill="url(#${p}-tiles)"/>
      <rect x="0" y="576" width="1920" height="96" fill="#7FA890" opacity="0.55"/>`;
    };
    /**
     * The laboratory, drawn once: the tiled wall, the shelf of jars, the enamel plate of the kitchen. The bench comes
     * after what hangs on the wall (C.bench): its top is at y = 772, where the specimen stands.
     */
    C.lab = function (p) {
      return `${C.wall(p)}
      <g id="${p}-wall" filter="url(#${p}-paper)">
        <rect x="110" y="330" width="540" height="24" fill="#8B6B4A" ${W}/>
        <path d="M150 354 l0 60 l40 -60Z M610 354 l0 60 l-40 -60Z" fill="#6F5338" ${W}/>
        ${jar(205, ["LEVURE", "épuisée", "en 2012"], "")}
        ${jar(380, ["SEL"], `<rect x="-66" y="-84" width="132" height="76" rx="8" fill="#FFFFFF"/>`)}
        ${jar(555, ["LANGUE", "DE BOIS"], `<path d="M-38 -8 L-48 -186 M-6 -8 L0 -182 M30 -8 L44 -186" stroke="#B9884F" stroke-width="16" stroke-linecap="round"/>`)}
        <rect x="1120" y="64" width="720" height="168" rx="10" fill="${C.GREEN}" ${W}/>
        <circle cx="1146" cy="90" r="7" fill="#C9D3CC"/><circle cx="1814" cy="90" r="7" fill="#C9D3CC"/><circle cx="1146" cy="206" r="7" fill="#C9D3CC"/><circle cx="1814" cy="206" r="7" fill="#C9D3CC"/>
        <text x="1480" y="136" text-anchor="middle" font-family="Bangers" font-size="64" fill="${C.CREAM}" letter-spacing="3">CUISINE DE RECHERCHE</text>
        <text x="1480" y="208" text-anchor="middle" font-family="Bangers" font-size="64" fill="${C.MUSTARD}" letter-spacing="3">DU VOTE UTILE</text>
      </g>`;
    };

    const CARDS = [
      { title: "TBILISSI, 2008", note: "CONSEILLER DU PRÉSIDENT", art: `<rect x="-205" y="-140" width="410" height="230" fill="#BFDCEB"/><path d="M-205 90 L-205 20 Q-120 -40 -40 10 Q40 -50 120 0 Q170 -30 205 10 L205 90Z" fill="#7FA890"/><path d="M40 -6 l0 -44 l14 -18 l14 18 l0 44Z M26 -6 h56 v20 h-56Z" fill="#E9DDBF"/><rect x="-170" y="-112" width="118" height="80" fill="#FFFFFF" stroke="#2A1B12" stroke-width="3"/><path d="M-111 -112v80M-170 -72h118" stroke="#D2232A" stroke-width="14"/><path d="M-141 -98v12M-147 -92h12M-81 -98v12M-87 -92h12M-141 -58v12M-147 -52h12M-81 -58v12M-87 -52h12" stroke="#D2232A" stroke-width="4"/>` },
      { title: "KIEV, 2013", note: "SUR LE MAÏDAN", art: `<rect x="-205" y="-140" width="410" height="115" fill="#2F6BD3"/><rect x="-205" y="-25" width="410" height="115" fill="#F5C400"/><path d="M-30 90 v-120 h60 v120Z" fill="#FFFDF4"/><path d="M-36 -30 Q-36 -74 0 -92 Q36 -74 36 -30Z" fill="#E0A526" stroke="#FFFFFF" stroke-width="4"/><path d="M0 -92v-26M-9 -108h18" stroke="#FFFDF4" stroke-width="5"/><path d="M-110 90 v-70 h40 v70Z M70 90 v-70 h40 v70Z" fill="#FFFDF4"/><path d="M-114 -20 Q-114 -48 -90 -58 Q-66 -48 -66 -20Z M66 -20 Q66 -48 90 -58 Q114 -48 114 -20Z" fill="#E0A526"/>` },
      { title: "NEW YORK", note: "", art: `<rect x="-205" y="-140" width="410" height="230" fill="#1E2A4A"/><circle cx="150" cy="-92" r="24" fill="#F6E9C8"/><path d="M-205 90 v-90 h50 v-60 h44 v40 h36 v-110 h50 v80 h40 v-50 h46 v90 h40 v-60 h50 v60 h54 v110Z" fill="#0F1730"/><path d="M-140 -40h12v12h-12ZM-140 -14h12v12h-12ZM-56 -100h12v12h-12ZM-56 -70h12v12h-12ZM-34 -40h12v12h-12ZM40 -70h12v12h-12ZM40 -40h12v12h-12ZM130 -30h12v12h-12ZM152 0h12v12h-12Z" fill="#F5C400"/><path d="M-178 90 v-70 h-8 l14 -34 l-4 -30 l10 -26 l6 26 l-2 30 l14 34 h-8 v70Z" fill="#5FB3A3"/>` },
      { title: "BERLIN", note: "", art: `<rect x="-205" y="-140" width="410" height="230" fill="#C9D3D8"/><path d="M-150 90 v-110 h300 v110 h-30 v-80 h-30 v80 h-30 v-80 h-30 v80 h-30 v-80 h-30 v80 h-30 v-80 h-30 v80Z" fill="#D9C79A"/><rect x="-164" y="-48" width="328" height="30" fill="#D9C79A"/><path d="M-40 -48 l20 -30 h40 l20 30Z" fill="#B9A677"/><path d="M168 90 v-190" stroke="#8E9AA0" stroke-width="8"/><circle cx="168" cy="-72" r="18" fill="#8E9AA0"/><path d="M168 -100v-36" stroke="#8E9AA0" stroke-width="4"/>` },
    ];
    /**
     * A postcard pinned to the wall, 430 by 300 at k = 1, centre at (x, y). `${id}-card-${n}` is the group a scene slams
     * in; n: 0 Tbilisi, 1 Kyiv, 2 New York, 3 Berlin.
     */
    C.postcard = function (id, n, { x, y, turn = 0, k = 1 }) {
      const card = CARDS[n];
      return `<g transform="translate(${x} ${y}) rotate(${turn}) scale(${k})"><g id="${id}-card-${n}">
        <rect x="-215" y="-150" width="430" height="300" fill="#FFFDF4" ${W}/>${card.art}
        ${card.note ? `<rect x="-205" y="-140" width="410" height="46" fill="#17110C"/><text x="0" y="-106" text-anchor="middle" font-family="Bangers" font-size="33" fill="${C.CREAM}" letter-spacing="2">${card.note}</text>` : ""}
        <text x="0" y="134" text-anchor="middle" font-family="Bangers" font-size="50" fill="${C.INK}" letter-spacing="2">${card.title}</text>
      </g></g>`;
    };

    C.bench = function (p) {
      return `<g id="${p}-bench" filter="url(#${p}-paper)">
        <rect x="-20" y="828" width="1960" height="280" fill="#6F8085"/>
        <path d="M480 828V1100M1440 828V1100" stroke="#5B6B70" stroke-width="6"/>
        <rect x="180" y="880" width="120" height="16" rx="8" fill="#C9D3D6"/><rect x="1620" y="880" width="120" height="16" rx="8" fill="#C9D3D6"/>
        <rect x="-20" y="772" width="1960" height="58" fill="#EFE6D2" ${W}/>
      </g>`;
    };

    /** The embossed label stuck under the specimen: white capitals on a black plastic strip. */
    C.label = function (id, { x, y, text, size = 34 }) {
      const w = text.length * size * 0.66 + 36;
      return `<g id="${id}" transform="translate(${x} ${y})"><rect x="${-w / 2}" y="${-size * 0.8}" width="${w}" height="${size * 1.6}" rx="4" fill="#17110C" stroke="#3A2E24" stroke-width="3"/>
        <text id="${id}-text" x="${-w / 2 + 18}" y="${size * 0.36}" font-family="Alegreya Sans" font-weight="700" font-size="${size}" fill="#FFFDF4" letter-spacing="${(size * 0.12).toFixed(1)}" xml:space="preserve"></text></g>`;
    };
    /** Print the first `n` letters of a label built by C.label. */
    C.print = function (id, text, n) {
      document.getElementById(`${id}-text`).textContent = text.slice(0, Math.max(0, Math.min(text.length, Math.floor(n))));
    };

    /* ------------------------------------------------------------------------------------------------------------------
     * The scene kit: a scene builds everything in its stage element (`${id}-stage`), so a composition file holds little
     * more than its script. Boxes, subtitles and slams are shown and hidden by the scene's own timeline.
     * ---------------------------------------------------------------------------------------------------------------- */
    const make = (parent, style, text) => {
      const el = document.createElement("div");
      el.setAttribute("style", style);
      if (text != null) el.textContent = text;
      parent.appendChild(el);
      return el;
    };
    C.make = make;
    /** Show an element at `at`, hide it `hold` seconds later (never, without `hold`). */
    C.show = function (tl, el, at, hold) {
      tl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.01 }, at);
      if (hold != null) tl.to(el, { opacity: 0, duration: 0.01 }, at + hold);
    };
    /** A word or a piece that slams in: big, then its size, in four frames. */
    C.slam = (tl, el, at, origin = "0% 50%") => tl.fromTo(el, { scale: 1.7, opacity: 0, transformOrigin: origin }, { scale: 1, opacity: 1, duration: 0.13, ease: "expo.out" }, at);
    /** The same for a group of the drawing whose own origin is its centre. */
    C.slamArt = (tl, selector, at, from = 1.7) => tl.fromTo(selector, { scale: from, opacity: 0, svgOrigin: "0 0" }, { scale: 1, opacity: 1, duration: 0.13, ease: "expo.out" }, at);

    /** The stage of a scene: a camera (`cam`) that holds the drawing (`svg`, 1920 by 1080), and a fixed layer for the boxes. */
    C.scene = function (id, { bleed = 40 } = {}) {
      const stage = document.getElementById(`${id}-stage`);
      stage.setAttribute("style", "position:absolute;inset:0;overflow:hidden;");
      const cam = make(stage, `position:absolute;inset:${-bleed}px;transform-origin:${960 + bleed}px ${540 + bleed}px;`);
      const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      svg.setAttribute("id", `${id}-art`);
      svg.setAttribute("viewBox", "0 0 1920 1080");
      svg.setAttribute("style", `position:absolute;left:${bleed}px;top:${bleed}px;width:1920px;height:1080px;`);
      cam.appendChild(svg);
      const over = make(stage, "position:absolute;inset:0;");
      return { id, stage, cam, svg, over, bleed };
    };
    /** Move the camera of a scene: a shake in pixels, a zoom around the point (cx, cy) of the drawing. */
    C.camera = function (S, { x = 0, y = 0, scale = 1, cx = 960, cy = 540 } = {}) {
      S.cam.style.transformOrigin = `${cx + S.bleed}px ${cy + S.bleed}px`;
      S.cam.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${scale.toFixed(4)})`;
    };
    /** A scene in the laboratory: what hangs on the wall (`wall`), the bench, then what stands on it (`things`). */
    C.labo = function (id, things, wall = "") {
      const S = C.scene(id);
      S.svg.innerHTML = C.lab(id) + (wall ? `<g filter="url(#${id}-paper)">${wall}</g>` : "") + C.bench(id) + `<g filter="url(#${id}-paper)">${things}</g>`;
      return S;
    };

    /** A page may ask for the pictures alone (the footage of a trailer): no report, no subtitle, no tag, no bubble. */
    const bare = () => window.SANS_TEXTE === true;
    const BOX = "position:absolute;left:50%;transform:translateX(-50%);padding:20px 44px;border:6px solid #2A1B12;background:#FFFDF4;font:700 60px/1.1 'Alegreya Sans',sans-serif;color:#2A1B12;white-space:nowrap;box-shadow:8px 10px 0 rgba(0,0,0,0.35);opacity:0;";
    /** The laboratory's reports, one box at a time: lines are [at, hold, text]. */
    C.reports = function (tl, S, number, lines, { top = null } = {}) {
      if (bare()) return;
      for (const [at, hold, text] of lines) {
        const box = make(S.over, BOX + (top == null ? "bottom:62px;" : `top:${top}px;`), text);
        make(box, "position:absolute;left:-6px;top:-50px;height:44px;padding:4px 18px 0;background:#E0A526;border:6px solid #2A1B12;border-bottom:none;font:400 30px/1.2 'Bangers',sans-serif;letter-spacing:2px;color:#2A1B12;", `RAPPORT N° ${number}`);
        C.show(tl, box, at, hold);
      }
    };
    /** Subtitles of a real recording, yellow on a black box: lines are [at, hold, text]. */
    C.subs = function (tl, S, lines) {
      if (bare()) return;
      for (const [at, hold, text] of lines) C.show(tl, make(S.over, "position:absolute;left:50%;bottom:56px;transform:translateX(-50%);padding:12px 34px 14px;background:#17110C;font:700 66px/1.1 'Alegreya Sans',sans-serif;color:#FFD23F;white-space:nowrap;opacity:0;", text), at, hold);
    };
    /** Where and when a recording or a sentence comes from, top left. */
    C.tag = (S, text) => bare() ? null : make(S.over, "position:absolute;left:60px;top:50px;padding:10px 26px;background:#17110C;font:700 38px/1.2 'Alegreya Sans',sans-serif;letter-spacing:2px;color:#F6E9C8;white-space:nowrap;", text);
    /** A speech bubble for a real sentence we have no recording of: his words, and their date under them. */
    C.bubble = function (tl, S, at, hold, text, source, { x, y, width = 760 }) {
      if (bare()) return null;
      const bubble = make(S.over, `position:absolute;left:${x}px;top:${y}px;width:${width}px;padding:24px 34px 20px;border:6px solid #14110C;border-radius:40px;background:#FFFDF4;font:700 54px/1.12 'Alegreya Sans',sans-serif;color:#14110C;text-align:center;box-shadow:7px 9px 0 rgba(0,0,0,0.35);opacity:0;`, text);
      make(bubble, "margin-top:8px;font:700 34px/1.2 'Alegreya Sans',sans-serif;color:#8A5A2B;", source);
      C.show(tl, bubble, at, hold);
      return bubble;
    };

    const DOUGH = "#F0DDB0";
    /** Flour and still water, stirred: a bowl of paste with his head in it, the poster brush planted beside. */
    C.glue = function (id, { x, y, k = 1, faces = ["glucksmann"] }) {
      const head = C.head(`${id}-head`, { x: 0, y: -180, k: 0.8, faces });
      return { head, inner: `${id}-in`, markup: `<g id="${id}" transform="translate(${x} ${y}) scale(${k})"><g id="${id}-in">
        <ellipse cx="0" cy="-196" rx="214" ry="46" fill="#C3CED2" ${W}/>
        <ellipse cx="0" cy="-196" rx="190" ry="34" fill="#FBF7EC"/>
        <g transform="rotate(22 150 -200)"><rect x="138" y="-440" width="28" height="250" rx="9" fill="#B9884F" ${W}/><rect x="128" y="-236" width="48" height="44" fill="#8E9AA0" ${W}/></g>
        ${head.markup}
        <path d="M-136 -190 Q-70 -150 0 -164 Q70 -150 136 -190 Q70 -176 0 -180 Q-70 -176 -136 -190Z" fill="#FBF7EC" stroke="#E6DFCB" stroke-width="4"/>
        <path d="M-214 -196 Q-204 -40 -112 0 L112 0 Q204 -40 214 -196 Q0 -146 -214 -196Z" fill="#E3E8EA" ${W}/>
        <path d="M-160 -176 q-8 64 2 98 q10 18 18 -6 q6 -52 -2 -88Z M118 -172 q-6 44 2 70 q8 14 14 -4 q4 -38 0 -64Z" fill="#FBF7EC" stroke="#E6DFCB" stroke-width="3"/>
        <g transform="rotate(-3)"><rect x="-92" y="-118" width="184" height="74" rx="8" fill="#FFFDF4" stroke="${C.INK}" stroke-width="4"/>
        <text x="0" y="-60" text-anchor="middle" font-family="Bangers" font-size="62" fill="${C.INK}" letter-spacing="3" data-layout-allow-overlap>COLLE</text></g>
      </g></g>` };
    };
    /** Kneaded, the paste turns elastic: a ball of dough, his head on top, flour on the bench. */
    C.dough = function (id, { x, y, k = 1, faces = ["glucksmann"] }) {
      const head = C.head(`${id}-head`, { x: 0, y: -276, k: 0.8, faces });
      return { head, inner: `${id}-in`, markup: `<g id="${id}" transform="translate(${x} ${y}) scale(${k})"><ellipse cx="0" cy="-6" rx="250" ry="22" fill="#FFFFFF" opacity="0.75"/><g id="${id}-in">
        ${head.markup}
        <path d="M-206 -118 Q-216 -288 0 -292 Q216 -288 206 -118 Q200 0 0 0 Q-200 0 -206 -118Z" fill="${DOUGH}" ${W}/>
        <path d="M-128 -226 q44 -34 100 -22" stroke="#FBF0D0" stroke-width="16" fill="none" stroke-linecap="round"/>
        <path d="M-150 -62 q150 52 300 0" stroke="#DFC88F" stroke-width="6" fill="none" stroke-linecap="round"/>
      </g></g>` };
    };
    const MAN = "M-60 -340 Q-110 -340 -120 -300 L-240 -262 Q-280 -246 -268 -212 Q-254 -182 -214 -196 L-116 -226 L-108 -170 L-128 -40 Q-134 0 -92 0 L-52 0 Q-22 0 -20 -36 L0 -130 L20 -36 Q22 0 52 0 L92 0 Q134 0 128 -40 L108 -170 L116 -226 L214 -196 Q254 -182 268 -212 Q280 -246 240 -262 L120 -300 Q110 -340 60 -340Z";
    /** The man-shaped tin of the primary, alone: where the dough will be pressed. Feet at (x, y). */
    C.tin = (id, { x, y, k = 1 }) => `<g id="${id}" transform="translate(${x} ${y}) scale(${k})"><path d="${MAN}" fill="#8E9AA0" ${W} transform="scale(1.14)"/><path d="${MAN}" fill="#5F6B70" transform="translate(0 -8)"/></g>`;
    /** The dough once pressed in the tin: a gingerbread man of raw dough (golden once baked), his head on it. Feet at (x, y). */
    C.doughman = function (id, { x, y, k = 1, faces = ["glucksmann"], baked = false, tin = false }) {
      const head = C.head(`${id}-head`, { x: 0, y: -322, k: 0.72, faces });
      return { head, inner: `${id}-in`, markup: `<g id="${id}" transform="translate(${x} ${y}) scale(${k})"><g id="${id}-in">
        ${tin ? `<path d="${MAN}" fill="#8E9AA0" ${W} transform="scale(1.14)"/>` : ""}
        <path d="${MAN}" fill="${baked ? "#D9A441" : DOUGH}" ${W}/>
        <circle cx="0" cy="-286" r="13" fill="#C0392B"/><circle cx="0" cy="-240" r="13" fill="#C0392B"/><circle cx="0" cy="-194" r="13" fill="#C0392B"/>
        ${head.markup}
      </g></g>` };
    };

    /**
     * The oven, feet at (x, y): 560 wide, 500 high. `${id}-glow` is the light behind the glass, `${id}-in` holds what
     * bakes (its origin is the middle of the oven floor), `${id}-door` the door, `${id}-hand` the hand of the timer.
     */
    C.oven = function (id, { x, y, k = 1, inside = "" }) {
      return `<g id="${id}" transform="translate(${x} ${y}) scale(${k})">
        <rect x="-280" y="-500" width="560" height="500" rx="18" fill="#C9CFD2" ${W}/>
        <rect x="-250" y="-472" width="500" height="72" rx="10" fill="#8E9AA0"/>
        <circle cx="-190" cy="-436" r="22" fill="${C.INK}"/><circle cx="-120" cy="-436" r="22" fill="${C.INK}"/>
        <g transform="translate(150 -436)"><circle r="28" fill="#FFFDF4" stroke="${C.INK}" stroke-width="4"/><path id="${id}-hand" d="M0 0 L0 -20" stroke="#C0262D" stroke-width="6" stroke-linecap="round"/></g>
        <rect x="-230" y="-372" width="460" height="322" rx="12" fill="#3A2317"/>
        <rect id="${id}-glow" x="-230" y="-372" width="460" height="322" rx="12" fill="#F08A24" opacity="0.5"/>
        <g id="${id}-in" transform="translate(0 -66)">${inside}</g>
        <path d="M-230 -62 H230" stroke="#17110C" stroke-width="10"/>
        <g id="${id}-door"><rect x="-244" y="-386" width="488" height="350" rx="14" fill="none" stroke="#6F8085" stroke-width="26"/><rect x="-150" y="-398" width="300" height="20" rx="10" fill="#4F5C61"/></g>
        <rect x="-250" y="-10" width="60" height="10" fill="#6F8085"/><rect x="190" y="-10" width="60" height="10" fill="#6F8085"/>
      </g>`;
    };

    /**
     * Inside the oven, seen through the glass of its door: the warm dark, the rack, the frame of the window. What
     * bakes is drawn after it. `${id}-cold` is the daylight that comes in when someone opens the door.
     */
    C.ovenView = function (id) {
      return `<rect x="-60" y="-60" width="2040" height="1200" fill="#3A2317"/>
        <ellipse cx="960" cy="1020" rx="1100" ry="620" fill="#F08A24" opacity="0.45"/><ellipse cx="960" cy="1060" rx="760" ry="380" fill="#FFC861" opacity="0.35"/>
        <path d="M-60 200 H1980 M-60 250 H1980" stroke="#2A1B12" stroke-width="10" opacity="0.6"/>
        <rect x="-60" y="980" width="2040" height="34" fill="#17110C"/><path d="${Array.from({ length: 14 }, (_, i) => `M${60 + i * 140} 980 V1140`).join(" ")}" stroke="#17110C" stroke-width="12"/>
        <rect id="${id}-cold" x="-60" y="-60" width="2040" height="1200" fill="#DCEBF0" opacity="0"/>`;
    };
    /** The frame of the oven's window, over what bakes. */
    C.ovenFrame = () => `<rect x="-10" y="-10" width="1940" height="1100" rx="70" fill="none" stroke="#6F8085" stroke-width="80"/><rect x="34" y="34" width="1852" height="1012" rx="46" fill="none" stroke="#4F5C61" stroke-width="10"/>`;
    /** A dial with a needle (`${id}-needle`, turn it around 0 0: -70 is empty, 70 is full). */
    C.gauge = function (id, { x, y, title }) {
      return `<g transform="translate(${x} ${y})"><path d="M-190 40 A190 190 0 0 1 190 40Z" fill="#FFFDF4" ${W}/>
        <path d="M-150 30 A150 150 0 0 1 -75 -100" fill="none" stroke="#C0262D" stroke-width="22"/><path d="M-75 -100 A150 150 0 0 1 75 -100" fill="none" stroke="${C.MUSTARD}" stroke-width="22"/><path d="M75 -100 A150 150 0 0 1 150 30" fill="none" stroke="#3F8F4F" stroke-width="22"/>
        <path id="${id}-needle" d="M-8 0 L0 -150 L8 0Z" fill="${C.INK}"/><circle r="18" fill="${C.INK}"/>
        <rect x="-190" y="52" width="380" height="70" rx="8" fill="${C.INK}"/><text x="0" y="104" text-anchor="middle" font-family="Bangers" font-size="54" fill="${C.CREAM}" letter-spacing="4">${title}</text></g>`;
    };

    /**
     * An election-night board. rows: { name, text, value, star }; the starred row is his. C.count shows the rows one
     * by one, each bar growing from the left.
     */
    C.board = function (id, { title, rows, x = 60, y = 60, width = 1400 }) {
      const top = Math.max(...rows.map((r) => r.value));
      const lines = rows.map((r, i) => {
        const yy = 176 + i * 104;
        const w = Math.max(10, (r.value / top) * 520);
        const ink = r.star ? C.MUSTARD : C.CREAM;
        return `<g id="${id}-row-${i}" opacity="0">
          <text x="40" y="${yy + 50}" font-family="Alegreya Sans" font-weight="700" font-size="50" fill="${ink}">${r.name}</text>
          <rect id="${id}-bar-${i}" x="640" y="${yy}" width="${w.toFixed(0)}" height="66" fill="${r.star ? C.MUSTARD : "#7C8B8F"}"/>
          <text x="${(640 + w + 24).toFixed(0)}" y="${yy + 54}" font-family="Bangers" font-size="${r.star ? 74 : 60}" fill="${ink}" letter-spacing="2">${r.text}</text>
        </g>`;
      }).join("");
      return `<g id="${id}" transform="translate(${x} ${y})"><rect width="${width}" height="${200 + rows.length * 104}" rx="14" fill="#17110C" stroke="#3A2E24" stroke-width="6"/>
        <text x="40" y="104" font-family="Bangers" font-size="80" fill="${C.CREAM}" letter-spacing="4">${title}</text>
        <path d="M40 132 H${width - 40}" stroke="${C.ORANGE}" stroke-width="8"/>${lines}</g>`;
    };
    C.count = function (tl, id, times) {
      times.forEach((at, i) => {
        C.show(tl, `#${id}-row-${i}`, at);
        tl.fromTo(`#${id}-bar-${i}`, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.3, ease: "power2.out" }, at);
      });
    };

    /** When the refrain's words fall, in seconds of its scene. Two blows: the promise, then what it was, two beats later
     * (Kevin MacLeod's « Gearhead », 68 to the minute). The victory, on « Final Fight » (bars of two seconds), adds its
     * last card and lets the solo fade. */
    C.PUNCH = { beat: 60 / 68, a: 0, b: 0, c: 2 * 60 / 68, d: 2 * 60 / 68, tag: 2 * 60 / 68 + 0.45, label: 2 * 60 / 68 + 0.05, print: 0.25, end: 2 * 60 / 68 + 1.95 };
    C.VICTORY = { beat: 0.5, a: 0, b: 0, c: 2, d: 2, tag: 3, label: 2.05, print: 0.25, next: 4, end: 8.5 };
    /**
     * The refrain every episode ends on: the specimen on stage under the rays, the lines slammed on the music, the label
     * printed, and what comes next. o: { times, lines: [a, b, c, d], sizes: [b, d], tag, label, next,
     * specimen(id, at) -> { markup, head, inner } (or pose(dx, squash) for a puppet), extra(id, at) -> what slides in
     * with the tag (the carafe) }.
     */
    C.refrain = function (tl, id, o) {
      const A = window.Anime;
      const T = o.times;
      const S = C.scene(id, { bleed: 50 });
      const SX = 1490, SY = 965;
      const spec = o.specimen(`${id}-spec`, { x: SX, y: SY });
      const seed = A.rng(55);
      const puffs = [];
      let cloud = "";
      for (let i = 0; i < 18; i++) {
        const angle = -Math.PI * (0.05 + 0.9 * seed());
        puffs.push({ dx: Math.cos(angle) * (260 + seed() * 420), dy: Math.sin(angle) * (200 + seed() * 380) });
        cloud += `<circle id="${id}-puff-${i}" cx="${SX}" cy="${SY - 330}" r="${(26 + seed() * 46).toFixed(0)}" fill="#FFFDF4" stroke="#E9DDBF" stroke-width="5" opacity="0"/>`;
      }
      const labelWidth = o.label.length * 40 * 0.66 + 36;
      S.svg.innerHTML = `<defs>${C.paper(`${id}-paper`)}</defs>
        <rect x="-60" y="-60" width="2040" height="1200" fill="#2A1B12"/>
        <path id="${id}-burst" fill="${C.ORANGE}"/>
        <path d="M-40 -60 L420 -60 L${SX + 250} ${SY} L${SX - 250} ${SY}Z" fill="${C.CREAM}" opacity="0.13"/>
        <path d="M1960 -60 L1560 -60 L${SX - 250} ${SY} L${SX + 250} ${SY}Z" fill="${C.CREAM}" opacity="0.13"/>
        <rect x="-60" y="${SY - 6}" width="2040" height="200" fill="#17110C"/>
        <path d="M-60 ${SY + 40} H1980 M-60 ${SY + 92} H1980" stroke="#2A1B12" stroke-width="5"/>
        <g filter="url(#${id}-paper)">${spec.markup}<g id="${id}-extra">${o.extra ? o.extra(`${id}-x`, { x: 1800, y: SY }) : ""}</g></g>
        <g>${cloud}</g>
        ${C.label(`${id}-label`, { x: 110 + labelWidth / 2, y: 872, text: o.label, size: 40 })}`;
      const LINE = "position:absolute;font-family:'Bangers',sans-serif;white-space:nowrap;line-height:1;-webkit-text-stroke:20px #17110C;paint-order:stroke fill;text-shadow:12px 12px 0 #5A2E1A;opacity:0;";
      const sizes = o.sizes || [276, 340];
      const la = make(S.cam, LINE + "left:140px;top:190px;font-size:112px;color:#F6E9C8;letter-spacing:3px;", o.lines[0]);
      const lb = make(S.cam, LINE + `left:130px;top:326px;font-size:${sizes[0]}px;color:#E0A526;letter-spacing:6px;`, o.lines[1]);
      const lc = make(S.cam, LINE + "left:140px;top:170px;font-size:150px;color:#F6E9C8;letter-spacing:4px;", o.lines[2]);
      const ld = make(S.cam, LINE + `left:120px;top:330px;font-size:${sizes[1]}px;color:#E0A526;letter-spacing:8px;`, o.lines[3]);
      const tag = make(S.cam, "position:absolute;left:150px;top:748px;font:700 66px/1.1 'Alegreya Sans',sans-serif;color:#F6E9C8;white-space:nowrap;opacity:0;", o.tag);
      const next = make(S.cam, "position:absolute;left:150px;top:1040px;font:400 64px/1 'Bangers',sans-serif;letter-spacing:3px;color:#E0A526;white-space:nowrap;opacity:0;" + (o.nextStyle || ""), o.next || "");
      const flash = make(S.stage, "position:absolute;inset:0;background:#FFFDF4;opacity:0;");
      const burst = document.getElementById(`${id}-burst`);
      const inner = spec.inner ? document.getElementById(spec.inner) : null;
      const labelGroup = document.getElementById(`${id}-label`);
      A.drive(tl, T.end, (t) => {
        // The rays turn faster while the music builds to the last word, then settle.
        const build = T.d > T.c ? Math.max(0, Math.min(1, (t - T.c) / (T.d - T.c))) : 0;
        const turn = t * 0.1 + (t < T.c ? 0 : build * build * 1.4);
        burst.setAttribute("d", A.sunburst({ cx: SX, cy: 520, count: 26, turn }));
        const bounce = 0.035 * Math.exp(-(t % T.beat) * 9);
        const r = A.rng(2800 + Math.floor(t * 30));
        const tremble = t >= T.c && t < T.d ? build * 7 : 0;
        const hit = t >= T.d && t < T.d + 0.6 ? 0.12 * Math.exp(-(t - T.d) * 8) : 0;
        if (spec.pose) spec.pose((r() - 0.5) * tremble, bounce + hit);
        else inner.setAttribute("transform", `translate(${((r() - 0.5) * tremble).toFixed(1)} 0) scale(${(1 + bounce + hit).toFixed(3)} ${(1 - bounce - hit).toFixed(3)})`);
        if (spec.head) C.jaw(spec.head, 0);
        const s = A.shake(t, [{ at: T.a, amp: 16 }, { at: T.b, amp: 20 }, { at: T.c, amp: 14 }, { at: T.d, amp: 40 }]);
        C.camera(S, { x: s.x, y: s.y });
        puffs.forEach((p, i) => {
          const k = Math.max(0, Math.min(1, (t - T.d) / 1.1));
          const out = 1 - Math.pow(1 - k, 3);
          const el = document.getElementById(`${id}-puff-${i}`);
          el.setAttribute("transform", `translate(${(p.dx * out).toFixed(1)} ${(p.dy * out + 160 * k * k).toFixed(1)})`);
          el.setAttribute("opacity", t < T.d ? 0 : (1 - k * k).toFixed(2));
        });
        labelGroup.setAttribute("opacity", t < T.label ? 0 : 1);
        C.print(`${id}-label`, o.label, ((t - T.label) / (T.print || 0.8)) * o.label.length + 1);
      });
      const flashAt = (at) => { tl.fromTo(flash, { opacity: 0 }, { opacity: 0.9, duration: 0.01 }, at); tl.to(flash, { opacity: 0, duration: 0.01 }, at + 0.07); };
      flashAt(T.a);
      C.slam(tl, la, T.a);
      if (o.lines[1]) C.slam(tl, lb, T.b);
      tl.to([la, lb], { opacity: 0, duration: 0.01 }, T.c);
      C.slam(tl, lc, T.c);
      flashAt(T.d);
      C.slam(tl, ld, T.d);
      if (o.extra) tl.fromTo(`#${id}-extra`, { x: 420 }, { x: 0, duration: 0.35, ease: "back.out(1.4)" }, T.tag);
      tl.fromTo(tag, { opacity: 0, x: -40 }, { opacity: 1, x: 0, duration: 0.25, ease: "power3.out" }, T.tag);
      if (o.next) tl.fromTo(next, { opacity: 0, scale: 1.5, transformOrigin: "0% 50%" }, { opacity: 1, scale: 1, duration: 0.13, ease: "expo.out" }, T.next);
      return S;
    };
  })();
  return window.Cuisine;
}
